/**
 * Generate every platform's copy of the shared zlak-flow sources.
 *
 *   node scripts/sync.mjs           write the generated files
 *   node scripts/sync.mjs --check   fail when any generated file is stale
 *
 * Sources (packages/core):
 *   protocol/protocol.md            the workflow protocol, with {{placeholders}}
 *   protocol/usage.txt              the one usage line
 *   platforms/<platform>/*.md       what differs per platform: preamble, roles,
 *                                   coder-mechanisms (each must exist, may be empty)
 *   platforms/<platform>/platform.json  what the platform ships and where (see lib/platforms.mjs)
 *   config/coder.example.json       the coder.json template
 *   icon.svg                        the bundle icon
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { relative } from "node:path";
import { tomlMultiline } from "./lib/toml-subset.mjs";
import { pathToFileURL } from "node:url";
import {
  coreDir as core,
  platforms,
  repoRoot as flow,
} from "./lib/platforms.mjs";
const fromCore = (path) => readFileSync(core + path, "utf8");

const USAGE = fromCore("protocol/usage.txt").trim();

/**
 * Render the protocol for one platform.
 * @param platform - a folder name under platforms/.
 * @returns the protocol text, ending without a trailing newline.
 */
export function renderProtocol(platform) {
  const text = fromCore("protocol/protocol.md").replace(
    /\{\{([a-z-]+)\}\}/g,
    (_, name) => {
      if (name === "usage") return USAGE;
      const path = `platforms/${platform}/${name}.md`;
      if (!existsSync(core + path)) throw new Error(`missing fragment ${path}`);
      return fromCore(path).trim();
    },
  );
  return text.replace(/\n{3,}/g, "\n\n").trim();
}

/** A JS string literal, ASCII only, so generated source stays escape-stable. */
const jsString = (text) =>
  JSON.stringify(text).replace(
    /[\u007f-￿]/g,
    (c) => "\\u" + c.charCodeAt(0).toString(16).padStart(4, "0"),
  );

/** A template-literal body that evaluates back to `text`. */
const templateBody = (text) =>
  text.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");

const TEMPLATE_START =
  "    // @generated-start coder-template: packages/core/config/coder.example.json, run pnpm sync";
const TEMPLATE_END = "    // @generated-end coder-template";

/**
 * Append the run's input section after rendering, so a host placeholder such as
 * Gemini's `{{args}}` is never read as one of core's own fragments.
 * @param {string} text - a rendered protocol.
 * @param {string} args - the host's input placeholder.
 * @returns {string} the protocol followed by the input section.
 */
export function appendInput(text, args) {
  return `${text}\n\n## This run's input\n\n${args}\n`;
}

/** Per-format builders for the shipped protocol file. */
const formats = {
  "skill-md": (platform) =>
    fromCore(`platforms/${platform.id}/${platform.header}`).replace(
      "{{usage-args}}",
      USAGE.replace(/^\/zlak-flow /, ""),
    ) +
    "\n" +
    appendInput(renderProtocol(platform.id), platform.args),
  "toml-command": (platform) =>
    [
      `# Generated by packages/core. Edit packages/core/protocol and packages/core/platforms/${platform.id}, then run pnpm sync.`,
      `description = ${JSON.stringify(platform.description)}`,
      `prompt = ${tomlMultiline(appendInput(renderProtocol(platform.id), platform.args))}`,
      "",
    ].join("\n"),
  "js-module": (platform) =>
    [
      "// Generated by packages/core. Edit packages/core/protocol and",
      `// packages/core/platforms/${platform.id}, then run pnpm sync.`,
      "",
      "/** The usage line shown for an empty or invalid /zlak-flow. */",
      `export const USAGE = ${jsString("Usage: " + USAGE)}`,
      "",
      "/** The workflow protocol the /zlak-flow command hands to the model. */",
      `export const PROTOCOL = ${jsString(renderProtocol(platform.id))}`,
      "",
    ].join("\n"),
};

/**
 * Every generated file: its path from the repository root and a function
 * producing its content from the current content.
 * @type {[string, (current: string) => string][]}
 */
const outputs = [];
for (const platform of platforms()) {
  const build = formats[platform.format];
  if (!build)
    throw new Error(`${platform.id}: unknown format ${platform.format}`);
  const dir = `packages/${platform.id}/`;
  outputs.push([dir + platform.output, () => build(platform)]);
  for (const { from, to } of platform.copies) {
    outputs.push([dir + to, () => fromCore(from)]);
  }
  const client = platform.clientTemplate;
  if (client) {
    outputs.push([
      dir + client,
      (current) => {
        const start = current.indexOf(TEMPLATE_START);
        const end = current.indexOf(TEMPLATE_END);
        if (start < 0 || end < start)
          throw new Error(`${client}: coder-template markers not found`);
        const block = `${TEMPLATE_START}\n    const CODER_TEMPLATE = \`${templateBody(fromCore("config/coder.example.json"))}\`;\n`;
        return current.slice(0, start) + block + current.slice(end);
      },
    ]);
  }
}

/** Write the generated files, or with check only report the stale ones. */
function main(check) {
  const stale = [];
  for (const [path, produce] of outputs) {
    const file = flow + path;
    const current = existsSync(file) ? readFileSync(file, "utf8") : "";
    const next = produce(current);
    if (next === current) continue;
    stale.push(path);
    if (!check) writeFileSync(file, next);
  }

  if (check && stale.length > 0) {
    console.error(
      `Stale generated files (run pnpm sync):\n${stale.map((p) => "  " + p).join("\n")}`,
    );
    process.exit(1);
  }
  console.log(
    check
      ? "agent-plugin-flow core: generated files are current"
      : stale.length === 0
        ? "agent-plugin-flow core: nothing to update"
        : `agent-plugin-flow core: updated ${stale.map((p) => relative(".", flow + p)).join(", ")}`,
  );
}

if (import.meta.url === pathToFileURL(process.argv[1]).href)
  main(process.argv.includes("--check"));
